<div class="admin-panel-heading"><div><span class="admin-eyebrow">ARTICLE ORGANIZATION</span><h2>Categories</h2></div><a class="admin-button" href="<?= e(admin_url('cms/articles')) ?>">Back to CMS</a></div><section class="admin-panel admin-list-panel"><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Name</th><th>Slug</th><th>Articles</th><th>Order</th><th>Edit</th></tr></thead><tbody><?php foreach($categories as $category): ?><tr><td><?= e($category['name']) ?></td><td><?= e($category['slug']) ?></td><td><?= (int)$category['article_count'] ?></td><td><?= (int)$category['display_order'] ?></td><td><details><summary class="admin-button">Edit category</summary><form method="post" action="<?= e(admin_url('cms/categories/'.(int)$category['id'])) ?>" class="admin-form-grid"><?= admin_csrf_field() ?><label>Name<input name="name" required maxlength="100" value="<?= e($category['name']) ?>"></label><label>Slug<input name="slug" required maxlength="110" value="<?= e($category['slug']) ?>"></label><label>Description<input name="description" maxlength="255" value="<?= e($category['description']??'') ?>"></label><label>Order<input type="number" name="display_order" min="0" max="65535" value="<?= (int)$category['display_order'] ?>"></label><button class="admin-button admin-button-primary">Save</button></form></details></td></tr><?php endforeach; ?></tbody></table></div></section><section class="admin-panel admin-form-panel"><h2>Create category</h2><form method="post" action="<?= e(admin_url('cms/categories')) ?>" class="admin-form-grid"><?= admin_csrf_field() ?><label>Name<input name="name" required maxlength="100"></label><label>Slug<input name="slug" required maxlength="110"></label><label>Description<input name="description" maxlength="255"></label><label>Order<input type="number" name="display_order" min="0" max="65535" value="0"></label><button class="admin-button admin-button-primary">Create category</button></form></section>
